# BitNet 1.58-bit Inference Pseudocode

# BitLinear Layer
class BitLinear:
    def __init__(self, in_features, out_features, weight):
        self.weight = weight  # Ternary weights: {-1, 0, 1}
        self.weight_packed = pack_ternary(self.weight)  # 16 weights per int32

    def forward(self, x):
        # x: (batch_size, in_features)
        # weight_packed: (out_features, packed_size)

        output = [0] * out_features

        for i in range(out_features):
            packed_weights = self.weight_packed[i]
            acc = 0

            for j in range(0, len(x), 16):
                chunk = x[j:j+16]
                w_bits = packed_weights[j//16]

                # Unrolled add/subtract/skip
                for k in range(16):
                    if k >= len(chunk): break
                    if (w_bits >> k) & 1:
                        if w_bits & (1 << (k + 16)):
                            acc -= chunk[k]  # -1
                        else:
                            acc += chunk[k]  # +1
                    # else: skip (0)

            output[i] = acc

        return output

# Quantization
def absmean_quantize(weights):
    abs_weights = [abs(w) for w in weights]
    threshold = 0.5 * mean(abs_weights)

    quantized = []
    for w in weights:
        if w > threshold:
            quantized.append(1)
        elif w < -threshold:
            quantized.append(-1)
        else:
            quantized.append(0)

    return quantized

# Packing
def pack_ternary(weights):
    packed = []
    for i in range(0, len(weights), 16):
        chunk = weights[i:i+16]
        bits = 0
        for j, w in enumerate(chunk):
            if w == 1:
                bits |= 1 << j
            elif w == -1:
                bits |= 1 << (j + 16)
        packed.append(bits)
    return packed
